* { box-sizing: border-box; }
:root {
  color-scheme: light;
  --ink: #182b3a;
  --muted: #536b72;
  --cream: #fff8e8;
  --paper: #fffdf7;
  --teal: #177e78;
  --coral: #db6655;
  --gold: #efb94e;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  color: var(--ink);
  background-color: #182b3a;
  background-image: radial-gradient(#294656 1.5px, transparent 1.5px);
  background-size: 18px 18px;
}
.game-card {
  width: min(100%, 960px);
  padding: clamp(22px, 5vw, 48px);
  border: 4px solid var(--ink);
  border-radius: 10px;
  background: var(--cream);
  box-shadow: 10px 10px 0 #0d1a24;
}
.heading { text-align: center; margin-bottom: 30px; }
.eyebrow, .label { color: var(--teal); font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
.eyebrow { margin: 0 0 8px; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 5vw, 3rem); line-height: 1.1; letter-spacing: -.04em; }
h1 span { color: var(--coral); }
.intro { margin: 12px 0 0; color: var(--muted); font-size: 1.05rem; }
.game-layout { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(220px, .75fr); gap: clamp(20px, 4vw, 40px); align-items: center; }
.board-wrap { min-width: 0; }
.board { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); border: 4px solid var(--ink); background: var(--ink); gap: 3px; }
.cell {
  position: relative;
  aspect-ratio: 1;
  min-width: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: var(--paper);
  font-weight: 800;
}
.cell:nth-child(4n + 2), .cell:nth-child(4n + 3) { background: #f1e6c9; }
.cell-number { position: absolute; top: 5px; left: 7px; color: #536b72; font-size: clamp(.68rem, 1.5vw, .9rem); }
.cell-mark { font-size: clamp(1.15rem, 3vw, 2rem); font-weight: 900; }
.cell.ladder { background: #d8eee2; color: var(--teal); }
.cell.snake { background: #f9ded3; color: var(--coral); }
.cell.finish { background: #f8e4a7; }
.token { position: absolute; right: 5px; bottom: 2px; color: var(--ink); font-size: clamp(1.25rem, 3vw, 2rem); line-height: 1; text-shadow: 0 1px 0 white; }
.legend { display: flex; flex-wrap: wrap; gap: 12px 20px; justify-content: center; margin-top: 14px; color: var(--muted); font-size: .9rem; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.legend-mark { display: inline-grid; width: 24px; height: 24px; place-items: center; border-radius: 5px; font-style: normal; font-weight: 900; }
.ladder-mark { color: var(--teal); background: #d8eee2; }
.snake-mark { color: var(--coral); background: #f9ded3; }
.player-mark { color: var(--ink); background: #f8e4a7; }
.panel { padding: 22px; border: 3px solid var(--ink); border-radius: 8px; background: var(--paper); box-shadow: 5px 5px 0 #d8cdaF; text-align: center; }
.position-box { display: grid; gap: 4px; }
.position-box strong { font-size: 3.5rem; line-height: 1; }
.dice-box { display: grid; justify-items: center; gap: 7px; margin-top: 20px; }
.die { display: grid; width: 58px; height: 58px; place-items: center; border: 3px solid var(--ink); border-radius: 9px; background: white; font-size: 2rem; font-weight: 800; box-shadow: 3px 3px 0 var(--ink); }
.message { min-height: 3.3em; margin: 20px 0 14px; color: var(--muted); font-weight: 650; }
.message.win { color: var(--teal); }
button { width: 100%; min-height: 50px; padding: 10px 16px; border: 3px solid var(--ink); border-radius: 6px; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s ease, box-shadow .12s ease, background-color .12s ease; }
button:focus-visible { outline: 4px solid var(--gold); outline-offset: 4px; }
.roll-button { color: white; background: var(--teal); box-shadow: 4px 4px 0 var(--ink); font-size: 1.15rem; }
.roll-button:hover { background: #116a65; transform: translate(-1px, -1px); box-shadow: 5px 5px 0 var(--ink); }
.roll-button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--ink); }
.roll-button:disabled { cursor: default; opacity: .65; transform: none; box-shadow: 4px 4px 0 var(--ink); }
.reset-button { margin-top: 12px; background: #f1e6c9; }
.reset-button:hover { background: #ead8ad; }
.reset-button:active { transform: translateY(2px); }
.rule-note { margin: 18px 0 0; color: var(--muted); font-size: .85rem; }
footer { margin-top: 30px; color: var(--muted); font-size: .9rem; text-align: center; }
@media (max-width: 650px) {
  body { padding: 18px 12px; }
  .game-card { padding: 22px 16px; }
  .heading { margin-bottom: 22px; }
  .game-layout { grid-template-columns: 1fr; }
  .panel { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; align-items: center; padding: 18px; }
  .position-box, .dice-box { margin: 0; }
  .message { grid-column: 1 / -1; min-height: auto; margin: 2px 0; }
  .roll-button, .reset-button { margin: 0; }
  .rule-note { grid-column: 1 / -1; margin: 0; }
}
@media (max-width: 390px) {
  .cell-number { top: 3px; left: 4px; }
  .token { right: 2px; }
  .panel { padding: 14px; }
}

const ladders = new Map([[3, 11], [8, 17], [20, 27]]);
const snakes = new Map([[14, 5], [24, 16], [29, 9]]);
const board = document.querySelector('#board');
const positionDisplay = document.querySelector('#position');
const dieDisplay = document.querySelector('#die');
const message = document.querySelector('#message');
const rollButton = document.querySelector('#roll-button');
const resetButton = document.querySelector('#reset-button');
let position = 1;

function renderBoard() {
  board.replaceChildren();
  for (let square = 30; square >= 1; square--) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Square ${square}`);
    const number = document.createElement('span');
    number.className = 'cell-number';
    number.textContent = square;
    cell.append(number);
    const ladderStart = [...ladders].find(([start]) => start === square);
    const ladderEnd = [...ladders].find(([, end]) => end === square);
    const snakeStart = [...snakes].find(([start]) => start === square);
    const snakeEnd = [...snakes].find(([, end]) => end === square);
    if (ladderStart || ladderEnd) {
      const destination = ladderStart ? ladderStart[1] : ladderEnd[0];
      cell.classList.add('ladder');
      cell.setAttribute('aria-label', `Square ${square}, ladder ${ladderStart ? `${square} to ${destination}` : `${destination} to ${square}`}`);
      const mark = document.createElement('span');
      mark.className = 'cell-mark';
      mark.setAttribute('aria-hidden', 'true');
      mark.textContent = ladderStart ? '↗' : '▥';
      cell.append(mark);
    } else if (snakeStart || snakeEnd) {
      const destination = snakeStart ? snakeStart[1] : snakeEnd[0];
      cell.classList.add('snake');
      cell.setAttribute('aria-label', `Square ${square}, snake ${snakeStart ? `${square} to ${destination}` : `${destination} to ${square}`}`);
      const mark = document.createElement('span');
      mark.className = 'cell-mark';
      mark.setAttribute('aria-hidden', 'true');
      mark.textContent = snakeStart ? '↘' : '〰';
      cell.append(mark);
    }
    if (square === 30) cell.classList.add('finish');
    if (square === position) {
      const token = document.createElement('span');
      token.className = 'token';
      token.setAttribute('aria-label', 'Your token');
      token.textContent = '●';
      cell.append(token);
    }
    board.append(cell);
  }
}

function roll() {
  if (position === 30) return;
  const result = Math.floor(Math.random() * 6) + 1;
  dieDisplay.textContent = result;
  dieDisplay.setAttribute('aria-label', `Rolled ${result}`);
  const next = position + result;
  if (next > 30) {
    message.textContent = `Rolled ${result}. You need an exact roll to reach 30.`;
    return;
  }
  position = next;
  let update = `Rolled ${result}. You moved to square ${position}.`;
  if (ladders.has(position)) {
    const from = position;
    position = ladders.get(position);
    update = `Rolled ${result}. Ladder from ${from} to ${position}!`;
  } else if (snakes.has(position)) {
    const from = position;
    position = snakes.get(position);
    update = `Rolled ${result}. Snake from ${from} to ${position}.`;
  }
  positionDisplay.textContent = position;
  if (position === 30) {
    update = `Rolled ${result}. You reached square 30. You win!`;
    message.classList.add('win');
    rollButton.disabled = true;
  }
  message.textContent = update;
  renderBoard();
}

function reset() {
  position = 1;
  positionDisplay.textContent = position;
  dieDisplay.textContent = '—';
  dieDisplay.setAttribute('aria-label', 'No roll yet');
  message.textContent = 'Ready? Roll to begin!';
  message.classList.remove('win');
  rollButton.disabled = false;
  renderBoard();
}

rollButton.addEventListener('click', roll);
resetButton.addEventListener('click', reset);
renderBoard();
